// Package testchain gives integration tests a real Anvil chain in Docker,
// and helpers to drive it: mine, snapshot and revert, send from Anvil's
// unlocked dev accounts, and deploy Waybill's contracts from compiled
// bytecode (contracts.json, regenerated by `make fixtures`).
//
// Import only from _test.go files.
package testchain

import (
	"context"
	"testing"
	"time"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ethereum/go-ethereum/ethclient"
	"github.com/ethereum/go-ethereum/rpc"
	"github.com/testcontainers/testcontainers-go"
	"github.com/testcontainers/testcontainers-go/wait"
)

// Image is the same Foundry image and version as deploy/compose.yaml.
const Image = "ghcr.io/foundry-rs/foundry:v1.8.3"

// Dev0 is Anvil's first dev account, unlocked by default and funded with
// 10,000 ETH. Its private key is Anvil's published test key; Waybill never
// stores it.
var Dev0 = common.HexToAddress("0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266")

// Anvil is a running chain.
type Anvil struct {
	RPC    *rpc.Client
	Client *ethclient.Client
	URL    string
	t      *testing.T
}

// Start runs a fresh Anvil for the test (chain id 31337) and stops it at
// cleanup. It skips the test under -short.
func Start(t *testing.T, args ...string) *Anvil {
	t.Helper()
	if testing.Short() {
		t.Skip("starts Anvil in Docker; skipped with -short")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
	defer cancel()
	ctr, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
		ContainerRequest: testcontainers.ContainerRequest{
			Image:        Image,
			Entrypoint:   []string{"anvil"},
			Cmd:          append([]string{"--host", "0.0.0.0", "--chain-id", "31337"}, args...),
			ExposedPorts: []string{"8545/tcp"},
			WaitingFor:   wait.ForListeningPort("8545/tcp"),
		},
		Started: true,
	})
	testcontainers.CleanupContainer(t, ctr)
	if err != nil {
		t.Fatalf("start anvil: %v", err)
	}
	endpoint, err := ctr.PortEndpoint(ctx, "8545/tcp", "http")
	if err != nil {
		t.Fatal(err)
	}
	c, err := rpc.DialContext(context.Background(), endpoint)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(c.Close)
	return &Anvil{RPC: c, Client: ethclient.NewClient(c), URL: endpoint, t: t}
}

// Call makes a JSON-RPC call and fails the test on error.
func (a *Anvil) Call(result any, method string, args ...any) {
	a.t.Helper()
	if err := a.RPC.CallContext(context.Background(), result, method, args...); err != nil {
		a.t.Fatalf("%s: %v", method, err)
	}
}

// Mine mines n blocks.
func (a *Anvil) Mine(n int) {
	a.t.Helper()
	a.Call(nil, "anvil_mine", hexutil.EncodeUint64(uint64(n))) //nolint:gosec // small counts
}

// Send sends a transaction from an unlocked dev account and returns its
// hash. With automine on (the default), it is mined at once.
func (a *Anvil) Send(from, to common.Address, data []byte) common.Hash {
	a.t.Helper()
	var h common.Hash
	a.Call(&h, "eth_sendTransaction", map[string]any{"from": from, "to": to, "data": hexutil.Bytes(data), "gas": "0x1000000"})
	return h
}

// Fund sets an account's ETH balance.
func (a *Anvil) Fund(addr common.Address, wei string) {
	a.t.Helper()
	a.Call(nil, "anvil_setBalance", addr, wei)
}
